SELECT CASE WHEN products.stock_qty >= 366 THEN 'high' WHEN products.stock_qty >= 138 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(inventory.quantity) AS quantity_count FROM inventory LEFT JOIN products ON inventory.product_id = products.id WHERE inventory.quantity <= 223 GROUP BY CASE WHEN products.stock_qty >= 366 THEN 'high' WHEN products.stock_qty >= 138 THEN 'mid' ELSE 'low' END HAVING quantity_count >= 4
